def validate_schema(schema):
    if (type(schema) is not dict or schema.get("name") != TOOLSET
            or type(schema.get("tools")) is not list or len(schema["tools"]) != 2):
        raise RuntimeError("Exact existing AuthoringTools projected two-builder schema required")
    if [r.get("name") if type(r) is dict else None for r in schema["tools"]] != [TOOLSET + "." + m for m in BINDINGS]:
        raise RuntimeError("Original NodeSample13/Asset20 ordered method names required")
    for method, row, expected in zip(BINDINGS, schema["tools"], _PUBLIC_SCHEMA["tools"]):
        if row.get("inputSchema") != expected["inputSchema"] or row.get("outputSchema") != expected["outputSchema"]:
            raise RuntimeError("Original builder collections/defaults and standard11 IO differ")
        inputs = row["inputSchema"];output = row["outputSchema"];inner = output["properties"]["returnValue"]
        if (tuple(inputs["properties"]) != PUBLIC_FIELDS_BY_METHOD[method]
                or inputs.get("additionalProperties") is not False
                or output.get("additionalProperties") is not False or inner.get("additionalProperties") is not False):
            raise RuntimeError("Original builder ordered fields and object flags differ")
        for field, value in DEFAULTS_BY_METHOD[method].items():
            actual = inputs["properties"][field].get("default")
            if type(actual) is not type(value) or actual != value:
                raise RuntimeError("Original builder default type/value differs: " + field)
        for field, kind in FIELD_KINDS_BY_METHOD[method].items():
            if kind == "nullable_any_list" and inputs["properties"][field].get("items") != {}:
                raise RuntimeError("Original List[Any] descriptor members must remain unrestricted")
    return {"schema_verified": True, "original_public_defaults_verified": True,
        "public_input_counts": {m: len(PUBLIC_FIELDS_BY_METHOD[m]) for m in BINDINGS}, "preparation_required": False}
